<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require BASE_PATH.'/app/AdminUi.php';$user=Auth::requireLogin();Auth::requirePermission('settings.manage');$pdo=Database::connection();$sql='SELECT l.*,u.name user_name FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id';$args=[];if(($user['role']??'')==='company_manager'){$sql.=' WHERE l.user_id IN (SELECT id FROM users WHERE company_id=?)';$args[]=(int)$user['company_id'];}$sql.=' ORDER BY l.id DESC LIMIT 500';$q=$pdo->prepare($sql);$q->execute($args);$rows=$q->fetchAll();admin_page_start('سجل نشاط النظام',$user);echo '<section class="panel"><table><thead><tr><th>المستخدم</th><th>العملية</th><th>النوع</th><th>الوصف</th><th>IP</th><th>التاريخ</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.e($r['user_name']??'النظام').'</td><td>'.e($r['action_key']).'</td><td>'.e($r['entity_type']).'</td><td>'.e($r['description']).'</td><td>'.e($r['ip_address']).'</td><td>'.e($r['created_at']).'</td></tr>';if(!$rows)echo '<tr><td colspan="6">لا توجد سجلات.</td></tr>';echo '</tbody></table></section>';admin_page_end();
